// Complex nested data transformation
const data = $input.item.json;

// Deep merge function
const deepMerge = (target, source) => {
  for (const key in source) {
    if (source[key] instanceof Object && key in target) {
      Object.assign(source[key], deepMerge(target[key], source[key]));
    }
  }
  return Object.assign(target || {}, source);
};

// Create complex nested structure
const result = {
  user: {
    profile: {
      name: {
        first: data['user.profile.firstName'],
        last: data['user.profile.lastName'],
        full: `${data['user.profile.firstName']} ${data['user.profile.lastName']}`
      },
      contact: {
        email: {
          primary: data['user.contact.email.primary'],
          verified: true
        }
      },
      stats: {
        logins: data['user.stats.loginCount'],
        lastLogin: new Date().toISOString()
      },
      preferences: {
        notifications: {
          email: data['user.preferences.emailNotifications'],
          push: false
        }
      }
    },
    metadata: {
      source: {
        system: data['metadata.source.system'],
        version: '1.0'
      },
      timestamps: {
        created: data['metadata.timestamp'],
        updated: new Date().toISOString()
      }
    }
  }
};

return { json: result };
